public class MaxSumSubarray {
    public static int findMaxSumSubarray(int[] arr, int k) {
        if (arr == null || arr.length < k)
            throw new IllegalArgumentException("Array too small for window size");

        int windowSum = 0;
        for (int i = 0; i < k; i++) windowSum += arr[i];   // initial window [0, k-1]
        int maxSum = windowSum;

        for (int i = k; i < arr.length; i++) {
            windowSum += arr[i] - arr[i - k];              // slide: add right, drop left
            maxSum = Math.max(maxSum, windowSum);
        }
        return maxSum;
    }

    public static void main(String[] args) {
        int[] prices = {2, 1, 5, 1, 3, 2};
        System.out.println(findMaxSumSubarray(prices, 3));  // 9 (subarray [5,1,3])
    }
}
