import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class FindAnagrams {
    public static List<Integer> findAnagrams(String text, String pattern) {
        List<Integer> result = new ArrayList<>();
        if (text.length() < pattern.length()) return result;

        int[] patternFreq = new int[26];
        int[] windowFreq = new int[26];
        for (char c : pattern.toCharArray()) patternFreq[c - 'a']++;

        int k = pattern.length();
        for (int i = 0; i < k; i++) windowFreq[text.charAt(i) - 'a']++;   // first window
        if (Arrays.equals(patternFreq, windowFreq)) result.add(0);

        for (int i = k; i < text.length(); i++) {
            windowFreq[text.charAt(i - k) - 'a']--;   // remove leaving char
            windowFreq[text.charAt(i) - 'a']++;       // add entering char
            if (Arrays.equals(patternFreq, windowFreq)) result.add(i - k + 1);
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(findAnagrams("cbaebabacd", "abc"));  // [0, 6]
    }
}
